import AVFoundation

/// Soft start/stop blips (Resources/start.wav, stop.wav; generated by scripts/make_sounds.py).
enum Sounds {
    private static func player(_ name: String) -> AVAudioPlayer? {
        let url = Bundle.main.url(forResource: name, withExtension: "wav") ?? URL(fileURLWithPath: "Resources/\(name).wav")
        let p = try? AVAudioPlayer(contentsOf: url)
        p?.volume = 0.6
        p?.prepareToPlay()
        return p
    }
    private static let start = player("start")
    private static let stop = player("stop")

    /// Length of the start sound; the recording ignores the microphone this long so the blip is not transcribed.
    static var startDuration: Double { start?.duration ?? 0.12 }

    static func prepare() { _ = start; _ = stop }
    static func playStart() { start?.currentTime = 0; start?.play() }
    static func playStop() { stop?.currentTime = 0; stop?.play() }
}
